-- THE SHARED POSTGRES SCHEMA PRODUCTION RAN BEFORE THE ENERGY RELEASE.
--
-- `pg_dump --schema-only --no-owner --no-privileges` (Postgres 17.11) of a
-- database built by the boot code of commit 75995697 — the release deployed
-- when energy was merged: initStore/initPostgres and applyLedgerSchema (the
-- ledger), mirror_state and its last_stamp ALTER, tenant_telegram, the
-- agent_commands receipt ALTER, risk_periods, paper_checkpoints, the MCP and
-- group-chat schemas, announcements, tenant_settings (PgSettingsStore) and
-- grants (PgGrantStore). Comments, SET lines and the `public.` qualifier were
-- stripped so it loads into a test run's own schema.
--
-- The starting point of pg-upgrade.postgres.test.ts: every new or changed
-- statement is run against THIS, the tables as they really are, not as this
-- branch would have created them. Regenerate only for a new production
-- baseline, from that release's own boot code — never from this branch.
CREATE TABLE agent_commands (
    id text NOT NULL,
    agent_id text NOT NULL,
    kind text NOT NULL,
    created_at bigint NOT NULL,
    claimed_at bigint,
    done_at bigint,
    result text,
    args text,
    receipt text
);
CREATE TABLE agents (
    smart_account text NOT NULL,
    name text DEFAULT 'Robin'::text NOT NULL,
    owner_address text NOT NULL,
    session_key_address text NOT NULL,
    chain_id bigint NOT NULL,
    caps text NOT NULL,
    granted_at bigint NOT NULL,
    expires_at bigint NOT NULL,
    status text DEFAULT 'armed'::text NOT NULL,
    created_at bigint DEFAULT (EXTRACT(epoch FROM now()))::bigint NOT NULL,
    hwm_usdg double precision DEFAULT 0 NOT NULL,
    accrued_fee_usdg double precision DEFAULT 0 NOT NULL,
    epoch bigint DEFAULT 1 NOT NULL,
    mode text,
    beat_at bigint,
    sponsor_gas bigint,
    live_blocker text,
    x_handle text,
    x_verified bigint DEFAULT 0 NOT NULL,
    contributions_known bigint,
    contributions_why text,
    gas_accounting text,
    quality_at bigint,
    hwm_withdrawn_usdg double precision DEFAULT 0 NOT NULL
);
