CREATE INDEX chat_turns_chat_time ON chat_turns USING btree (chat_id, id DESC);
CREATE INDEX class_positions_agent ON class_positions USING btree (agent_id);
CREATE INDEX decisions_agent_time ON decisions USING btree (agent_id, at DESC);
CREATE INDEX decisions_time ON decisions USING btree (at DESC);
CREATE INDEX equity_agent_time ON equity USING btree (agent_id, at DESC);
CREATE INDEX events_agent_time ON events USING btree (agent_id, created_at DESC);
CREATE INDEX fee_accruals_agent_time ON fee_accruals USING btree (agent_id, at DESC);
CREATE INDEX flows_agent_time ON flows USING btree (agent_id, at DESC);
CREATE UNIQUE INDEX flows_chain_identity ON flows USING btree (chain_id, agent_id, tx_hash, log_index) WHERE ((tx_hash IS NOT NULL) AND (log_index IS NOT NULL));
CREATE INDEX flows_quarantine_agent ON flows_quarantine USING btree (agent_id);
CREATE INDEX groupchat_messages_tenant ON groupchat_messages USING btree (tenant, id);
CREATE INDEX journal_agent_epoch ON journal USING btree (agent_id, epoch, seq);
CREATE INDEX mcp_audit_at ON mcp_audit USING btree (at);
CREATE INDEX mcp_audit_connection ON mcp_audit USING btree (connection_id, at);
CREATE INDEX mcp_audit_tenant ON mcp_audit USING btree (tenant, at);
CREATE INDEX mcp_auth_requests_expiry ON mcp_auth_requests USING btree (expires_at);
CREATE INDEX mcp_clients_kind_created ON mcp_clients USING btree (kind, created_at);
CREATE INDEX mcp_clients_kind_expiry ON mcp_clients USING btree (kind, expires_at);
CREATE INDEX mcp_codes_expiry ON mcp_codes USING btree (expires_at);
CREATE UNIQUE INDEX mcp_connections_one_active ON mcp_connections USING btree (tenant, client_id, COALESCE(resource, ''::text)) WHERE ((status = 'active'::text) AND (kind = 'oauth'::text));
